-- 1학년 가정 활동 5개 추가 (2026-10-21): 수학 2 · 국어 2 · 과학 1
-- 활동 과목에 국어 허용 (밴드 1~2/3~4/5~6 유지)
do $$ declare c record; begin
  for c in select conname from pg_constraint where conrelid = 'public.activities'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%subject%' loop
    execute format('alter table public.activities drop constraint %I', c.conname);
  end loop;
end $$;
alter table public.activities add constraint activities_subject_check check (subject in ('국어','과학','수학','영어'));
alter table public.activities drop constraint if exists activities_band_check;
alter table public.activities add constraint activities_band_check check (band in ('1~2','3~4','5~6'));

insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order,published,grade,semester) values ('g1-count-caps','수학','1~2','9까지의 수','달걀판 병뚜껑 수 세기','10칸 달걀판에 병뚜껑을 하나씩 놓으며 9까지 세어요. 수 카드와 점 카드 짝 맞추기, 하나 더·하나 덜 놀이까지 해요.','난이도 ★☆☆ 쉬움','20분',array['병뚜껑은 어린 동생이 입에 넣지 않게 해 주세요']::text[],array['달걀판','병뚜껑']::text[],'assets/img/n_g1-count-caps.jpg',false,'assets/pdf/g1-number-cards.pdf',$j$[{"type": "materials", "note": "살 것 없음 · 병뚜껑을 10개 모아 두세요", "rows": [{"name": "10구 달걀판 1개", "how": "달걀 10개짜리 종이 판이에요. 5칸씩 2줄이라 수 세기 판으로 딱 좋아요. 30구 판이면 10칸만 써요.", "kit": false}, {"name": "병뚜껑 10개", "how": "페트병 뚜껑. 색이 섞여 있어도 괜찮아요.", "kit": false}, {"name": "수 카드·점 카드 도안", "how": "아래에서 내려받아 인쇄해요. 두꺼운 종이에 붙이면 오래 써요.", "kit": false}, {"name": "가위", "how": "카드 오리기용", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "notes": [], "items": [{"title": "카드 준비하기", "body": "도안을 인쇄해 수 카드(0~9)와 점 카드(0~9)를 오려요. 수 카드는 뒤집어서 한쪽에 쌓아 둬요.", "warn": "", "image": "assets/img/s_g1-count-caps_1.jpg"}, {"title": "카드 뽑고 병뚜껑 놓기", "body": "수 카드를 한 장 뽑아요. 6이 나왔다면 \"하나, 둘, 셋…\" 소리 내어 세며 병뚜껑 6개를 달걀판에 놓아요. 윗줄 5칸을 먼저 채우고 아랫줄로 내려가요.", "warn": "", "image": "assets/img/s_g1-count-caps_2.jpg"}, {"title": "점 카드와 짝 맞추기", "body": "수 카드마다 같은 수의 점 카드를 찾아 나란히 놓아요. 점을 하나씩 세지 않고 \"윗줄 5개에 3개 더, 8!\"처럼 한눈에 알아보면 더 좋아요.", "warn": "", "image": "assets/img/s_g1-count-caps_3.jpg"}, {"title": "하나 더, 하나 덜", "body": "달걀판에 병뚜껑 5개를 놓아요. 하나를 더 놓으면 6이에요. 다시 5개에서 하나를 빼면 4예요. 수 카드를 옆에 놓으며 확인해요.", "warn": "", "image": "assets/img/s_g1-count-caps_4.jpg"}, {"title": "숨은 수 찾기", "body": "1부터 9까지 수 카드를 순서대로 늘어놓고, 아이가 눈을 감은 사이 한 장을 뒤집어요. 어떤 수가 숨었는지 맞혀요. 병뚜껑이 하나도 없는 빈 달걀판은 0이에요.", "warn": "", "image": "assets/img/s_g1-count-caps_5.jpg"}]}, {"type": "template", "title": "수 카드·점 카드", "desc": "수 카드 0~9와 '하나 더·하나 덜' 카드, 달걀판과 같은 10칸 점 카드 0~9가 들어 있어요. A4 2장.", "pdf": "assets/pdf/g1-number-cards.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["병뚜껑 7개를 놓으면 달걀판에 빈칸은 몇 개 남나요?", "8보다 하나 더 큰 수와 하나 더 작은 수는 무엇일까요?", "빈 달걀판은 어떤 수 카드와 짝이 될까요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["수는 물건이 몇 개인지 알려 주는 약속이에요. 병뚜껑 6개도, 사탕 6개도, 친구 6명도 모두 6이라고 써요. 하나를 더 놓으면 바로 다음 수가 되고, 하나를 빼면 바로 앞의 수가 돼요. 하나도 없을 때는 0이라고 해요."]}, {"label": "부모님께", "paras": ["1학년 1학기 첫 단원 '9까지의 수'에서는 개수 세기, 수 읽기(하나·일)와 쓰기, 순서(첫째·둘째), 하나 더 큰 수와 하나 더 작은 수, 0을 배웁니다. 10칸 달걀판은 교실에서 쓰는 '10칸 틀'과 같은 구조라서, 5를 기준으로 수를 한눈에 알아보는 감각을 길러 주고 이후 10 만들기와 받아올림으로 자연스럽게 이어집니다. 숫자를 예쁘게 쓰는 것보다 '세는 말, 개수, 숫자'를 서로 연결하는 경험이 먼저입니다.", "이렇게 물어보세요: \"하나씩 세지 않고 몇 개인지 알 수 있는 방법이 있을까?\""]}]}, {"type": "more", "items": [{"title": "순서 놀이", "body": "병뚜껑을 한 줄로 세우고 \"빨간 뚜껑은 몇째일까?\" 물어봐요."}, {"title": "큰 수 가져가기", "body": "두 사람이 수 카드를 한 장씩 뽑아 더 큰 수가 나온 사람이 병뚜껑을 하나 가져가요."}, {"title": "집 안 6 찾기", "body": "숟가락 6개, 양말 6짝처럼 집 안에서 같은 수만큼 모아 봐요."}]}, {"type": "info", "items": [{"label": "도안", "value": "수 카드·점 카드 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "1학년 1학기 9까지의 수 (수 세기, 수 읽고 쓰기, 하나 더·하나 덜, 0) · 1학년 2학기 100까지의 수 준비"}]}]$j$::jsonb,49,true,1,1)
  on conflict (slug) do update set subject=excluded.subject, band=excluded.band, topic=excluded.topic, title=excluded.title, summary=excluded.summary, difficulty=excluded.difficulty, duration=excluded.duration, caution=excluded.caution, tags=excluded.tags, hero_image=excluded.hero_image, hero_is_doc=excluded.hero_is_doc, template_pdf=excluded.template_pdf, content=excluded.content, sort_order=excluded.sort_order, published=excluded.published, grade=excluded.grade, semester=excluded.semester, updated_at=now();
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order,published,grade,semester) values ('g1-shape-detective','수학','1~2','여러 가지 모양','재활용품 모양 탐정','집에 있는 상자, 휴지심, 공을 모아 세 가지 모양으로 나눠요. 굴려 보고 쌓아 보며 모양마다 다른 점을 찾아요.','난이도 ★☆☆ 쉬움','30분',array['깨지는 병과 날카로운 캔은 빼 주세요']::text[],array['상자','휴지심']::text[],'assets/img/n_g1-shape-detective.jpg',false,'assets/pdf/g1-shape-sort.pdf',$j$[{"type": "materials", "note": "살 것 없음 · 재활용품 정리하는 날 하면 좋아요", "rows": [{"name": "상자 모양 물건 2~3개", "how": "휴지 상자, 과자 상자, 작은 택배 상자", "kit": false}, {"name": "둥근기둥 모양 물건 2~3개", "how": "휴지심, 깨끗이 씻은 캔, 둥근 반찬통", "kit": false}, {"name": "공 모양 물건 2~3개", "how": "작은 공, 테니스공, 귤이나 오렌지", "kit": false}, {"name": "경사로", "how": "상자를 펼친 판이나 두꺼운 종이와 책 몇 권", "kit": false}, {"name": "모양 탐정 기록지", "how": "아래에서 내려받아 인쇄해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "notes": [], "items": [{"title": "단서 모으기", "body": "집 안을 돌며 상자처럼 생긴 것, 휴지심처럼 생긴 것, 공처럼 생긴 것을 2~3개씩 모아요. 탐정이 단서를 모으듯 장바구니에 담아 와요.", "warn": "캔은 입구가 날카롭지 않은지 어른이 먼저 확인해요.", "image": "assets/img/s_g1-shape-detective_1.jpg"}, {"title": "세 무리로 나누기", "body": "기록지를 펴고 물건을 상자 모양, 둥근기둥 모양, 공 모양으로 나눠 놓아요. 귤은 어디로 갈까요? 동글동글한 공 모양이에요.", "warn": "", "image": "assets/img/s_g1-shape-detective_2.jpg"}, {"title": "굴려 보기", "body": "책 위에 판을 기대어 경사로를 만들고 물건을 하나씩 굴려요. 상자는 멈춰 있고, 눕힌 캔은 한쪽으로 굴러가고, 공은 이리저리 잘 굴러가요.", "warn": "", "image": "assets/img/s_g1-shape-detective_3.jpg"}, {"title": "쌓아 보기", "body": "같은 모양끼리 높이 쌓아 봐요. 상자는 높이 쌓을 수 있고, 둥근기둥은 세우면 쌓을 수 있어요. 공은 자꾸 굴러떨어져요.", "warn": "", "image": "assets/img/s_g1-shape-detective_4.jpg"}, {"title": "기록하고 맞히기", "body": "알아낸 것을 기록지에 O, X로 적어요. 마지막으로 눈을 감고 물건을 만져 보며 어떤 모양인지 맞혀요. \"평평한 곳이 있어? 뾰족한 곳이 있어?\"", "warn": "", "image": "assets/img/s_g1-shape-detective_5.jpg"}]}, {"type": "template", "title": "모양 탐정 기록지", "desc": "찾은 물건을 세 가지 모양으로 나눠 적는 칸과 굴리기·쌓기 결과표가 들어 있어요. A4 1장.", "pdf": "assets/pdf/g1-shape-sort.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["둥근기둥 모양은 왜 눕히면 굴러가고, 세우면 굴러가지 않을까요?", "공 모양을 쌓으려면 어떻게 하면 좋을까요?", "우리 집에서 상자 모양이 가장 많은 곳은 어디일까요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["상자 모양은 평평한 면과 뾰족한 곳이 있어서 잘 쌓이지만 굴러가지 않아요. 둥근기둥 모양은 평평한 면과 둥근 면이 함께 있어서, 세우면 쌓을 수 있고 눕히면 굴러가요. 공 모양은 어느 쪽이나 둥글어서 어느 방향으로든 잘 굴러가요."]}, {"label": "부모님께", "paras": ["1학년 1학기 '여러 가지 모양'에서는 생활 속 물건을 상자 모양, 둥근기둥 모양, 공 모양으로 나누고 굴리기·쌓기로 특징을 알아봅니다. 교과서는 직육면체, 원기둥, 구 같은 정식 이름 대신 그림 기호나 '~ 모양'으로 부르니 집에서도 같은 말을 쓰면 좋습니다. 정답을 알려 주기보다 아이가 '왜 그렇게 나눴는지' 자기 기준을 말로 설명하게 하는 것이 핵심입니다.", "이렇게 물어보세요: \"이 물건은 왜 이 무리에 넣었어?\""]}]}, {"type": "more", "items": [{"title": "모양 로봇 만들기", "body": "모은 물건으로 로봇이나 기차를 만들고, 어떤 모양을 몇 개 썼는지 세어요."}, {"title": "모양 숨바꼭질", "body": "물건 하나를 보자기에 싸서 손으로만 만져 보고 모양을 맞혀요."}, {"title": "마트 모양 탐정", "body": "장 보러 가서 상자 모양 물건과 둥근기둥 모양 물건을 찾아봐요."}]}, {"type": "info", "items": [{"label": "도안", "value": "모양 탐정 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "1학년 1학기 여러 가지 모양 (상자·둥근기둥·공 모양 찾기, 굴리기와 쌓기) · 1학년 2학기 평면 모양(▢, △, ○)으로 이어져요"}]}]$j$::jsonb,50,true,1,1)
  on conflict (slug) do update set subject=excluded.subject, band=excluded.band, topic=excluded.topic, title=excluded.title, summary=excluded.summary, difficulty=excluded.difficulty, duration=excluded.duration, caution=excluded.caution, tags=excluded.tags, hero_image=excluded.hero_image, hero_is_doc=excluded.hero_is_doc, template_pdf=excluded.template_pdf, content=excluded.content, sort_order=excluded.sort_order, published=excluded.published, grade=excluded.grade, semester=excluded.semester, updated_at=now();
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order,published,grade,semester) values ('g1-consonant-cards','국어','1~2','자음','우유팩 자음 카드 놀이','다 마신 우유팩으로 ㄱ부터 ㅎ까지 자음 카드를 만들어요. 낱말의 첫소리를 찾고 그림 카드와 짝을 맞추며 자음과 친해져요.','난이도 ★☆☆ 쉬움','30분',array['우유팩 자르기는 어른과 함께']::text[],array['우유팩']::text[],'assets/img/n_g1-consonant-cards.jpg',false,'assets/pdf/g1-consonant-cards.pdf',$j$[{"type": "materials", "note": "살 것 없음 · 우유팩 2개면 카드 16장", "rows": [{"name": "우유팩 2개", "how": "1L 우유팩을 씻어 말린 뒤 펼쳐요. 한 면에서 카드 2장이 나와요. 4개면 그림 카드까지 만들 수 있어요.", "kit": false}, {"name": "자음 카드·그림 카드 도안", "how": "아래에서 내려받아 인쇄해요", "kit": false}, {"name": "가위, 풀", "how": "도안을 오려 우유팩 조각에 붙여요", "kit": false}, {"name": "매직펜", "how": "도안 없이 직접 크게 써도 좋아요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "notes": [], "items": [{"title": "우유팩 카드 자르기", "body": "씻어 말린 우유팩을 펼쳐서 한 면에 카드가 2장씩 나오게 네모로 잘라요. 우유팩은 물에 강하고 단단해서 오래 놀 수 있어요.", "warn": "우유팩은 두꺼워서 어른이 잘라 주세요.", "image": "assets/img/s_g1-consonant-cards_1.jpg"}, {"title": "자음 카드 만들기", "body": "도안의 자음 카드를 오려 우유팩 조각에 붙이거나 매직펜으로 크게 써요. ㄱ부터 ㅎ까지 14장을 순서대로 늘어놓고 \"기역, 니은, 디귿…\" 하고 이름을 불러 봐요.", "warn": "", "image": "assets/img/s_g1-consonant-cards_2.jpg"}, {"title": "첫소리 찾기", "body": "부모님이 그림 카드를 보여 주며 \"토끼!\" 하고 말해요. 아이는 맨 처음 소리 [ㅌ]을 듣고 ㅌ 카드를 찾아요. 모양과 소리가 비슷한 ㄷ, ㅋ 카드를 함께 두면 소리를 더 잘 구별해요.", "warn": "", "image": "assets/img/s_g1-consonant-cards_3.jpg"}, {"title": "짝 맞추기 놀이", "body": "자음 카드와 그림 카드를 섞어 모두 뒤집어 놓아요. 두 장씩 뒤집어서 ㅂ과 바나나처럼 첫소리가 맞으면 가져가요. 처음에는 6쌍으로 시작해요.", "warn": "", "image": "assets/img/s_g1-consonant-cards_4.jpg"}, {"title": "같은 첫소리 모으기", "body": "ㄱ 카드를 놓고 ㄱ으로 시작하는 낱말을 모아요. 가방, 기차, 고구마처럼 떠오르는 낱말을 말해 봐요. 나비는 ㄴ으로 시작하니까 빼요.", "warn": "", "image": "assets/img/s_g1-consonant-cards_5.jpg"}]}, {"type": "template", "title": "자음 카드·그림 낱말 카드", "desc": "이름이 함께 적힌 자음 카드 14장과, 첫소리가 하나씩 짝이 되는 그림 낱말 카드 14장, 빈 카드 4장이 들어 있어요. A4 2장.", "pdf": "assets/pdf/g1-consonant-cards.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["ㄱ과 ㅋ, ㄷ과 ㅌ은 모양이 어떻게 다른가요? 소리는 어떻게 다른가요?", "'오리'의 첫소리 ㅇ은 소리가 날까요?", "내 이름의 첫 글자는 어떤 자음으로 시작하나요?"]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["우리 글자는 자음과 모음이 만나서 만들어져요. ㄱ, ㄴ, ㄷ 같은 자음은 낱말 맨 앞에서 첫소리를 내요. '토끼'를 천천히 말해 보면 맨 처음에 [ㅌ] 소리가 나지요. ㅋ, ㅌ처럼 획이 하나 더 있는 자음은 바람이 더 세게 나와요. 그런데 글자 맨 앞의 ㅇ은 소리가 나지 않아요."]}, {"label": "부모님께", "paras": ["1학년 1학기 국어는 자음자와 모음자의 모양, 이름, 소리를 익히고 글자를 만드는 것으로 시작합니다. 이 시기에는 자음 이름을 외우는 것보다 낱말 속에서 첫소리를 듣고 찾아보는 경험이 읽기와 받아쓰기의 바탕이 됩니다. 첫소리 ㅇ은 소리가 나지 않는다는 점, ㄱ·ㅋ·ㄲ처럼 비슷한 소리를 구별하는 데 시간이 걸리는 점은 자연스러운 과정이니 놀이처럼 천천히 반복해 주세요.", "이렇게 물어보세요: \"'고양이'를 천천히 말해 볼까? 맨 처음에 어떤 소리가 났어?\""]}]}, {"type": "more", "items": [{"title": "내 이름 카드", "body": "가족 이름의 첫 자음 카드를 찾아 식탁 자리에 놓아요."}, {"title": "몸으로 자음 만들기", "body": "팔과 몸으로 ㄱ, ㄴ, ㅅ 모양을 만들고 서로 맞혀요."}, {"title": "첫소리 낱말 겨루기", "body": "자음 카드를 한 장 뽑아 그 소리로 시작하는 낱말을 누가 더 많이 말하나 겨뤄요."}]}, {"type": "info", "items": [{"label": "도안", "value": "자음 카드·그림 낱말 카드 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "1학년 1학기 국어 한글 익히기 (자음자의 이름과 모양, 첫소리 구별하기)"}]}]$j$::jsonb,51,true,1,1)
  on conflict (slug) do update set subject=excluded.subject, band=excluded.band, topic=excluded.topic, title=excluded.title, summary=excluded.summary, difficulty=excluded.difficulty, duration=excluded.duration, caution=excluded.caution, tags=excluded.tags, hero_image=excluded.hero_image, hero_is_doc=excluded.hero_is_doc, template_pdf=excluded.template_pdf, content=excluded.content, sort_order=excluded.sort_order, published=excluded.published, grade=excluded.grade, semester=excluded.semester, updated_at=now();
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order,published,grade,semester) values ('g1-batchim-caps','국어','1~2','받침','병뚜껑 받침 글자 블록','병뚜껑에 자음과 모음을 붙여 글자 블록을 만들어요. ''바''에 받침을 바꿔 끼우며 밤, 반, 밥, 발을 만들고 받아쓰기 놀이까지 해요.','난이도 ★★☆ 보통','30분',array['병뚜껑은 어린 동생이 입에 넣지 않게 해 주세요']::text[],array['병뚜껑']::text[],'assets/img/n_g1-batchim-caps.jpg',false,'assets/pdf/g1-batchim-record.pdf',$j$[{"type": "materials", "note": "살 것 없음 · 병뚜껑을 30개쯤 모아 두세요", "rows": [{"name": "병뚜껑 30개", "how": "페트병 뚜껑. 자음용과 모음용으로 색을 나누면 더 쉬워요.", "kit": false}, {"name": "글자 스티커 도안", "how": "도안의 동그라미를 오려 뚜껑에 붙여요. 네임펜으로 직접 써도 돼요.", "kit": false}, {"name": "글자 판·받아쓰기 기록지", "how": "같은 도안 둘째 장에 있어요", "kit": false}, {"name": "가위, 풀, 연필", "how": "스티커 붙이기와 받아쓰기용", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "notes": [], "items": [{"title": "글자 블록 만들기", "body": "자음은 파란 동그라미, 모음은 빨간 동그라미를 오려 병뚜껑 위에 붙여요. 받침에 자주 쓰는 ㄱ ㄴ ㄹ ㅁ ㅂ ㅇ은 하나씩 더 만들어요.", "warn": "", "image": "assets/img/s_g1-batchim-caps_1.jpg"}, {"title": "받침 없는 글자 만들기", "body": "글자 판에 첫소리와 모음을 놓아요. ㄱ 아래에 ㅗ를 놓으면 '고', ㅂ 옆에 ㅏ를 놓으면 '바'예요. ㅗ처럼 누운 모음은 아래에, ㅏ처럼 선 모음은 오른쪽에 놓아요.", "warn": "", "image": "assets/img/s_g1-batchim-caps_2.jpg"}, {"title": "받침 붙이기", "body": "글자 아래 받침 자리에 자음을 하나 더 놓아요. '고' 아래에 ㅇ을 놓으면 '공', '바' 아래에 ㅁ을 놓으면 '밤'이 돼요. 소리 내어 읽으며 입 모양이 어떻게 끝나는지 느껴 봐요.", "warn": "", "image": "assets/img/s_g1-batchim-caps_3.jpg"}, {"title": "받침 바꿔 보기", "body": "'바'는 그대로 두고 받침만 바꿔요. ㅁ이면 밤, ㄴ이면 반, ㅂ이면 밥, ㄹ이면 발이에요. 받침 하나로 뜻이 완전히 달라져요.", "warn": "", "image": "assets/img/s_g1-batchim-caps_4.jpg"}, {"title": "병뚜껑 받아쓰기", "body": "부모님이 낱말을 불러 주면 아이가 병뚜껑으로 먼저 만들고, 기록지에 연필로 써요. 맞으면 크게 표시해 줘요. 한 번에 5개면 충분해요.", "warn": "", "image": "assets/img/s_g1-batchim-caps_5.jpg"}]}, {"type": "template", "title": "글자 스티커·받아쓰기 기록지", "desc": "병뚜껑에 붙이는 자음·모음 스티커 30개, 글자 판 2가지, 받아쓰기 10칸과 불러 줄 낱말 예시가 들어 있어요. A4 2장.", "pdf": "assets/pdf/g1-batchim-record.pdf"}, {"type": "questions", "title": "생각해 봐요", "items": ["'공'에서 받침 ㅇ을 빼면 어떤 글자가 되나요?", "'달'의 받침을 ㄴ으로 바꾸면 어떤 낱말이 될까요?", "'옷'은 [옫]으로 소리 나는데, 왜 ㅅ 받침으로 쓸까요? '옷이'를 소리 내어 읽어 봐요."]}, {"type": "explain", "title": "개념 정리", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["글자 아래에 붙는 자음을 받침이라고 해요. '바'에 ㅁ 받침을 붙이면 입술을 꾹 다물며 '밤'이 되고, ㄴ을 붙이면 혀끝이 입천장에 닿으며 '반'이 돼요. 받침 하나만 바꿔도 전혀 다른 낱말이 되니까, 끝소리를 귀 기울여 들어야 해요."]}, {"label": "부모님께", "paras": ["1학년 1학기 후반에 받침이 있는 글자를 읽고 쓰기 시작하고, 2학기에는 소리와 글자가 다른 낱말과 받아쓰기가 본격적으로 나옵니다. 받아쓰기가 걱정될 때는 긴 문장보다 받침 하나만 다른 낱말(밤·반·밥·발)부터 연습하면 효과적입니다. 병뚜껑을 손으로 옮기며 첫소리, 모음, 받침 순서로 글자를 조립하면 소리를 듣고 나누어 글자로 옮기는 힘이 길러집니다. 틀린 글자는 지우기보다 병뚜껑 하나만 바꿔 다시 만들게 해 주세요.", "옷, 꽃처럼 소리([옫], [꼳])와 받침 글자가 다른 낱말은 '옷이[오시]', '꽃을[꼬츨]'처럼 뒤에 모음을 붙여 읽으면 원래 받침 소리가 들립니다.", "이렇게 물어보세요: \"받침 하나만 바꿔서 다른 낱말을 만들어 볼까?\""]}]}, {"type": "more", "items": [{"title": "받침 바꾸기 사슬", "body": "곰 → 공 → 강 → 감처럼 블록을 하나씩만 바꿔 낱말을 이어 가요."}, {"title": "거꾸로 받아쓰기", "body": "아이가 문제를 내고 부모님이 병뚜껑으로 만들어요. 일부러 틀리면 아이가 고쳐 줘요."}, {"title": "두 글자 낱말", "body": "병뚜껑을 더 모아 가방, 연필, 사랑처럼 두 글자 낱말을 만들어요."}]}, {"type": "info", "items": [{"label": "도안", "value": "글자 스티커·받아쓰기 기록지 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "1학년 1학기 받침이 있는 글자 읽고 쓰기 · 1학년 2학기 소리와 글자가 다른 낱말, 받아쓰기"}]}]$j$::jsonb,52,true,1,1)
