insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order,published,grade,semester) values ('g1-bottle-maracas','과학','1~2','소리','페트병 마라카스 소리 비교','작은 페트병에 쌀, 콩, 동전을 넣어 마라카스를 만들어요. 흔들어 보며 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 귀로 비교해요.','난이도 ★☆☆ 쉬움','30분',array['작은 재료는 어른이 지켜보며','뚜껑은 테이프로 단단히']::text[],array['페트병']::text[],'assets/img/n_g1-bottle-maracas.jpg',false,null,$j$[{"type": "materials", "note": "살 것 없음 · 부엌에 있는 재료로 만들어요", "rows": [{"name": "작은 페트병 3개", "how": "300~500mL 음료병. 라벨을 떼고 씻어 말려요.", "kit": false}, {"name": "쌀, 콩, 동전", "how": "병마다 한 가지씩. 병의 3분의 1쯤만 넣어요.", "kit": false}, {"name": "종이 깔때기", "how": "이면지를 고깔 모양으로 말아 만들어요", "kit": false}, {"name": "색 테이프", "how": "뚜껑을 감아 단단히 막아요. 병마다 색을 다르게 하면 구별하기 쉬워요.", "kit": false}, {"name": "가림판", "how": "상자를 펼친 판이나 큰 그림책", "kit": false}], "image": null}, {"type": "steps", "title": "만드는 방법", "notes": [], "items": [{"title": "재료 준비하기", "body": "라벨을 뗀 작은 페트병 3개와 쌀, 콩, 동전을 준비해요. 이면지를 고깔 모양으로 말아 깔때기를 만들어요.", "warn": "", "image": "assets/img/s_g1-bottle-maracas_1.jpg"}, {"title": "병에 넣기", "body": "깔때기를 병 입구에 꽂고 숟가락으로 쌀을 넣어요. 병의 3분의 1쯤 차면 멈춰요. 다른 병에는 콩, 또 다른 병에는 동전을 넣어요.", "warn": "콩과 동전은 작아서 입에 넣지 않도록 어른이 곁에서 지켜봐요.", "image": "assets/img/s_g1-bottle-maracas_2.jpg"}, {"title": "뚜껑 막기", "body": "뚜껑을 꼭 닫고 색 테이프로 뚜껑과 병목을 빙 둘러 감아요. 흔들다가 열리지 않게 단단히 막아요.", "warn": "테이프 마무리는 어른이 한 번 더 확인해 주세요.", "image": "assets/img/s_g1-bottle-maracas_3.jpg"}, {"title": "흔들어 비교하기", "body": "마라카스를 하나씩 흔들어요. 살살 흔들 때와 세게 흔들 때 소리 크기가 어떻게 다른가요? 쌀은 가늘고 높은 '사사삭', 콩은 굵고 낮은 '달그락', 동전은 '짤랑짤랑' 쇠 소리가 나요.", "warn": "", "image": "assets/img/s_g1-bottle-maracas_4.jpg"}, {"title": "소리 맞히기 놀이", "body": "가림판 뒤에서 부모님이 마라카스 하나를 흔들면, 아이는 눈앞의 마라카스를 보며 어떤 병인지 맞혀요. 역할을 바꿔서도 해 봐요.", "warn": "", "image": "assets/img/s_g1-bottle-maracas_5.jpg"}]}, {"type": "questions", "title": "관찰해 봐요", "items": ["쌀을 조금 넣은 병과 많이 넣은 병은 소리가 어떻게 다를까요?", "가장 높은 소리가 나는 마라카스는 무엇인가요? 가장 낮은 소리는요?", "마라카스를 흔들 때 손에 무엇이 느껴지나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["마라카스를 흔들면 안에 든 쌀알과 콩알이 병에 부딪히며 부르르 떨려요. 이 떨림이 공기를 타고 귀까지 와서 소리로 들려요. 세게 흔들면 더 세게 부딪혀서 큰 소리가 나요. 작고 가벼운 쌀알은 가늘고 높은 소리를, 크고 무거운 콩은 굵고 낮은 소리를 내요."]}, {"label": "부모님께", "paras": ["소리는 물체가 떨려서 생기고, 세게 떨릴수록 소리가 커집니다. 안에 든 알갱이의 크기와 재질에 따라 부딪히는 소리의 높낮이와 느낌(음색)이 달라집니다. 1학년 통합교과 즐거운 생활의 '주변의 소리 탐색하기, 악기 만들어 연주하기'와 연결되며, 3학년 과학 '소리의 성질'(소리의 세기와 높낮이)을 미리 경험해 보는 활동입니다. 정확한 용어보다 '크다·작다, 높다·낮다'를 귀로 구별해 자기 말로 표현하는 것이 목표입니다.", "이렇게 물어보세요: \"어떻게 하면 소리를 더 작게 만들 수 있을까?\""]}]}, {"type": "more", "items": [{"title": "동요에 맞춰 연주", "body": "좋아하는 동요에 맞춰 큰 소리, 작은 소리로 바꿔 가며 흔들어요."}, {"title": "재료 바꿔 보기", "body": "단추, 클립, 마른 국수를 넣으면 어떤 소리가 날지 먼저 예상하고 들어 봐요."}, {"title": "양 바꿔 보기", "body": "같은 쌀을 조금, 반, 가득 넣은 병 세 개를 만들어 소리를 비교해요."}]}, {"type": "note", "text": "안전: 콩, 동전처럼 작은 재료는 어린 동생이 삼키지 않도록 놀이가 끝나면 높은 곳에 보관해 주세요. 테이프가 헐거워지면 다시 감아 주세요."}, {"type": "info", "items": [{"label": "도안", "value": "필요 없어요"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "1학년 통합교과 즐거운 생활 (소리 탐색, 악기 만들어 연주하기) · 3학년 과학 소리의 성질 미리 보기"}]}]$j$::jsonb,53,true,1,2)
